public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] colors = new int[2 * n];
    for (int i = 0; i < 2 * n; i++) {
        colors[i] = sc.nextInt();
    }
    int count = 0;
    Map<Integer, List<Integer>> colorPositions = new HashMap<>();

    for (int i = 0; i < 2 * n; i++) {
        int color = colors[i];
        if (!colorPositions.containsKey(color)) {
            colorPositions.put(color, new ArrayList<>());
        }
        colorPositions.get(color).add(i);
    }

    for (List<Integer> positions : colorPositions.values()) {
        if (positions.size() == 2 && positions.get(1) - positions.get(0) == 2) {
            count++;
        }
    }

    System.out.print(count);
}
